      assessment360DeltaChip('Cintura',latest.measurements?.waist,base.measurements?.waist,'cm',1),
      assessment360DeltaChip('Abdômen',latest.measurements?.abdomen,base.measurements?.abdomen,'cm',1),
      assessment360DeltaChip('Quadril',latest.measurements?.hip,base.measurements?.hip,'cm',1)
