    if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){try{await navigator.share(data);toast('PDF Premium enviado ao compartilhamento do aparelho.');return true}catch(error){if(error?.name==='AbortError'){toast('Compartilhamento cancelado.');return false}throw error}}
